/**
 * Real F1 car telemetry (FastF1 / official timing) resampled to equal-distance.
 * Generated by scripts/fetch-f1-telemetry.py — not a physics guess.
 *
 * Prefer `loadTelemetry` (Result). `trackTelemetry` remains for lap-metrics
 * until U02 migrates call sites.
 */
import { err, type Result } from '@/lib/result'
import {
  parseTelemetry,
  type DomainError,
  type TelemetryTrace,
  type TrackTelemetry,
} from '@/track/domain'

export type { TelemetryTrace, TrackTelemetry }

const TELEMETRY_IDS = new Set(['spa', 'monza', 'texas'])

function loadRawTelemetry(trackId: string): unknown {
  return require(`./data/telemetry/${trackId}.json`)
}

/**
 * Load and validate telemetry for a track id.
 * Returns `not_found` when no FastF1 pack exists for that circuit.
 */
export function loadTelemetry(
  trackId: string,
): Result<TrackTelemetry, DomainError> {
  if (!TELEMETRY_IDS.has(trackId)) {
    return err({
      code: 'not_found',
      message: `No telemetry pack for track "${trackId}"`,
    })
  }
  return parseTelemetry(loadRawTelemetry(trackId))
}

/** Sync helper for existing callers. Null when missing or invalid. */
export function trackTelemetry(trackId: string): TrackTelemetry | null {
  const result = loadTelemetry(trackId)
  return result.ok ? result.value : null
}

/** Linear sample of an equal-distance series at lap fraction t ∈ [0, 1]. */
export function sampleTrace(series: readonly number[], t: number): number {
  const n = series.length
  if (n === 0) return 0
  if (n === 1) return series[0]!
  const u = ((t % 1) + 1) % 1
  const f = u * (n - 1)
  const i0 = Math.floor(f)
  const i1 = Math.min(n - 1, i0 + 1)
  const s = f - i0
  return series[i0]! + (series[i1]! - series[i0]!) * s
}
